# Two cores, one cache line; track each core's MESI state
state = ["I", "I"]

def read(c):
    if state[c] == "I":
        o = 1 - c
        if state[o] in ("M", "E", "S"):
            state[o] = "S"; state[c] = "S"   # owner supplies data, both Shared
        else:
            state[c] = "E"                   # nobody else has it
def write(c):
    state[1 - c] = "I"                       # invalidate the other copy
    state[c] = "M"

for name, op, c in [("core0 read", read, 0), ("core1 read", read, 1),
                    ("core0 write", write, 0), ("core1 read", read, 1),
                    ("core1 write", write, 1)]:
    op(c)
    print(f"{name:12s} -> core0={state[0]} core1={state[1]}")
# Expected: E/I, S/S, M/I, S/S, I/M

