public class Main {
    public static void main(String[] args) {
        int min = Integer.MIN_VALUE;
        // -(-2^31) does not fit in an int, so it wraps back to itself
        System.out.println("abs(MIN) = " + Math.abs(min));
        System.out.println("-MIN     = " + (-min));

        int lo = 1_500_000_000, hi = 2_000_000_000;
        System.out.println("(lo+hi)/2        = " + ((lo + hi) / 2));       // overflows
        System.out.println("lo+(hi-lo)/2     = " + (lo + (hi - lo) / 2));  // safe

        // Detect overflow before it happens
        int a = Integer.MAX_VALUE, b = 1;
        boolean willOverflow = b > 0 && a > Integer.MAX_VALUE - b;
        System.out.println("MAX + 1 overflows? " + willOverflow);
        try { Math.addExact(a, b); } catch (ArithmeticException e) {
            System.out.println("addExact threw: " + e.getMessage());
        }
        // Right shift rounds toward -infinity, division toward zero
        System.out.println("-7 >> 1 = " + (-7 >> 1) + ", -7 / 2 = " + (-7 / 2));
    }
}
